import{z as n,x as P,o as i,c as p,q as o,j as E,D as t,d as s,s as A,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const G=JSON.parse('{"title":"BGP 属性与决策","description":"","frontmatter":{"title":"BGP 属性与决策","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bgp-attributes-decision.md","filePath":"cs/bgp-attributes-decision.md","lastUpdated":1791413859000}'),B={name:"cs/bgp-attributes-decision.md"};function d(_,a,u,m,C,F){const r=P("Mermaid");return i(),p("div",null,[a[2]||(a[2]=o('<h1 id="bgp-属性与决策" tabindex="-1">BGP 属性与决策 <a class="header-anchor" href="#bgp-属性与决策" aria-label="Permalink to &quot;BGP 属性与决策&quot;">​</a></h1><div class="epigraph"><p>同一前缀多条路径时，决策过程按 LOCAL_PREF、AS_PATH、ORIGIN、MED、eBGP vs iBGP、IGP 度量、Router ID 逐步打破平局。</p><footer>—— 据 RFC 4271 第 9.1 节决策过程；Kurose and Ross BGP 属性整理</footer></div><p>主干<a href="/cs/bgp-policy">AS 路径与策略</a> 已给进出口直觉。<a href="/cs/rip">上一课</a> 对照了无政策的跳数。<a href="/cs/bgp-intuition">BGP 直觉</a> 不背阶梯。缺口是<strong>属性怎么排序</strong>：谁先谁后、哪些过 iBGP、哪些不。本课不把路由反射器写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IGP 选最小代价。BGP 选「政策最佳」。典型顺序：拒无效 → 最高 LOCAL_PREF → 最短 AS_PATH → 最低 ORIGIN → 最低 MED（同 AS）→ 偏 eBGP → 最近 IGP 下一跳 → 其它平局。LOCAL_PREF 不发给 eBGP 邻居，故是 AS 内部的客户优先旋钮。MED 可对外暗示入口，邻居可无视。</p><p><span class="marginnote">术语翻译：LOCAL_PREF 是「我们 AS 内部更偏爱谁」的打分牌，分越高越优先，只贴在自家墙上（不随 eBGP 外发）；MED 则是贴给邻居看的「请优先从我这进来」的提示牌，邻居可以根本不看。</span></p><p>不要把 AS_PATH 长度当延迟：绕远可以是故意的 LOCAL_PREF。</p><p><span class="marginnote">RFC 4271。厂商在阶梯里插入权重等私有步，课上以标准为主。Communities 是政策标签，本身不是阶梯里的一步，除非你的政策把它映到 LOCAL_PREF。</span></p><h3 id="不是最短跳" tabindex="-1">不是最短跳 <a class="header-anchor" href="#不是最短跳" aria-label="Permalink to &quot;不是最短跳&quot;">​</a></h3><p>LOCAL_PREF 内部优先于 AS_PATH。MED 可被邻居无视。下一跳必须 IGP 可达才有效。Communities 要映到阶梯才起作用。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>走一条例子：客户路由 vs 对等路由，LOCAL_PREF 已决定。再走 MED 选入口。画决策漏斗。对照 RIP：没有这些属性，无法表达合同。</p>',12)),(i(),E(l,null,{default:t(()=>[A(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%80%99%E9%80%89%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20LP%5B%22LOCAL_PREF%22%5D%0A%20%20LP%20--%3E%20ASP%5B%22AS_PATH%20%E9%95%BF%22%5D%0A%20%20ASP%20--%3E%20MED%5B%22MED%22%5D%0A%20%20MED%20--%3E%20NH%5B%22IGP%20%E5%88%B0%E4%B8%8B%E4%B8%80%E8%B7%B3%22%5D%0A%20%20NH%20--%3E%20BEST%5B%22%E5%AE%89%E8%A3%85%20FIB%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：同一前缀，客户路由 AS_PATH 是「65001」，对等路由是「65002 65003」。论 AS_PATH 客户短、本该赢；但若给客户路由打 LOCAL_PREF 200、对等 100，阶梯第一步就定了客户，根本轮不到数 AS_PATH——这就是「绕远可以是故意的」。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"选出的下一跳还要 IGP 可达（递归），否则无效——这把域内 SPF 与域间政策接起来。ECMP 在 BGP 里默认常关，多路径要额外开，避免环与不对称。主干 LPM 课：FIB 仍按最长前缀，BGP 只是填充某前缀的下一跳。",-1)),a[6]||(a[6]=e("p",null,"哪些属性跨 AS、哪些留在 AS 内：",-1)),(i(),E(l,null,{default:t(()=>[A(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20NE%5B%22eBGP%20%E8%BF%9B%E5%85%A5%EF%BC%9AAS_PATH%E3%80%81MED%20%E5%8F%AF%E8%A7%81%22%5D%20--%3E%20R1%5B%22%E5%85%A5%E5%8F%A3%E8%B7%AF%E7%94%B1%E5%99%A8%22%5D%0A%20%20R1%20--%3E%7C%22iBGP%20%E6%89%A9%E6%95%A3%EF%BC%9A%E9%99%84%20LOCAL_PREF%22%7C%20R2%5B%22iBGP%20%E5%90%8C%E4%BC%B4%22%5D%0A%20%20R2%20--%3E%20R3%5B%22%E5%87%BA%E5%8F%A3%E8%B7%AF%E7%94%B1%E5%99%A8%22%5D%0A%20%20R3%20--%3E%7C%22eBGP%20%E5%8F%91%E5%87%BA%EF%BC%9ALOCAL_PREF%20%E4%B8%8D%E5%8F%91%E9%80%81%22%7C%20NX%5B%22%E9%82%BB%E5%B1%85%20AS%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">为什么重要：BGP 的下一跳常是邻居 AS 的地址，域内路由表若查不到它，再「最佳」的路径也装不进转发表、整条作废。这道递归检查把域内 IGP 和域间政策拴在一起：域内断了，域间选得再好也白选。</span></p><p>收敛慢：属性抖动会反复决策，后课 dampening。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ADD-PATH 的全部。iBGP 与路由反射器是下一课。后课默认：eBGP 政策阶梯以 RFC 4271 为准；私有步要显式声明。</p><p>不要用 MED 当全球负载均衡：它只在同意比较的 AS 之间有意义。</p><p>下一课<a href="/cs/ibgp-route-reflector">iBGP 与路由反射器</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策是属性漏斗，不是最短跳。</li><li>LOCAL_PREF 内部，MED 对外可被忽略。</li><li>下一跳必须 IGP 可达。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4271；Kurose and Ross。</li></ul>',8))])}const c=n(B,[["render",d]]);export{G as __pageData,c as default};
